import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"第三册：培养技能 · 综合复习与自测 · 第12–23课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","frontmatter":{"title":"第三册：培养技能 · 综合复习与自测 · 第12–23课","description":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","splitFrom":"life/english/new-concept/book-3/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 综合复习与自测","summary":"全册逐课覆盖的原创练习、折叠答案和表达迁移任务。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 综合复习与自测 · 第1–11课","link":"/life/english/new-concept/book-3/review-part-01"},"next":{"text":"第三册：培养技能 · 综合复习与自测 · 第24–35课","link":"/life/english/new-concept/book-3/review-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 综合复习与自测 · 第1–11课","link":"/life/english/new-concept/book-3/review-part-01"},"next":{"text":"第三册：培养技能 · 综合复习与自测 · 第24–35课","link":"/life/english/new-concept/book-3/review-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-3/review-part-02.md","filePath":"life/english/new-concept/book-3/review-part-02.md"}'),n={name:"life/english/new-concept/book-3/review-part-02.md"};function r(l,e,i,h,p,d){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-综合复习与自测-·-第12–23课" tabindex="-1">第三册：培养技能 · 综合复习与自测 · 第12–23课 <a class="header-anchor" href="#第三册-培养技能-·-综合复习与自测-·-第12–23课" aria-label="Permalink to &quot;第三册：培养技能 · 综合复习与自测 · 第12–23课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-12-·-第二条件句的假设距离" tabindex="-1">Lesson 12 · 第二条件句的假设距离 <a class="header-anchor" href="#lesson-12-·-第二条件句的假设距离" aria-label="Permalink to &quot;Lesson 12 · 第二条件句的假设距离 {#lesson-12-·-第二条件句的假设距离}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If I lived on a remote island, I would choose a reliable radio over a television.</p><h3 id="练习-1-11" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-11" aria-label="Permalink to &quot;练习 1 {#练习-1-11}&quot;">​</a></h3><p>例句中的 lived 是否说明说话者以前住过岛上？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> 过去式用于表达假设距离。</p></details><p><strong>表达迁移：</strong> 为独处一周的虚构情境列出一个优先物品、一个理由和一个限制。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>If I stayed in a remote cabin, I would bring a radio. It could help me receive weather warnings. I would still need a safe way to leave in an emergency.</p><p>所有选择围绕具体需求，最后一句补足单一工具无法解决的限制。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-012">回看本课</a></p><h2 id="lesson-13-·-强调句的焦点" tabindex="-1">Lesson 13 · 强调句的焦点 <a class="header-anchor" href="#lesson-13-·-强调句的焦点" aria-label="Permalink to &quot;Lesson 13 · 强调句的焦点 {#lesson-13-·-强调句的焦点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> It was the gardener&#39;s voice that finally reassured the visitor.</p><h3 id="练习-1-12" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-12" aria-label="Permalink to &quot;练习 1 {#练习-1-12}&quot;">​</a></h3><p>还原例句为普通句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The gardener&#39;s voice finally reassured the visitor.</p><p><strong>解析：</strong> 删除强调框架后保留完整主谓宾。</p></details><p><strong>表达迁移：</strong> 写三句身份误会，最后用强调句说明消除误会的线索。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A tall figure stood behind the curtain. I thought a stranger had entered the room. It was my sister&#39;s laugh that made me relax.</p><p>先展示视觉误导，再交代推测，最后突出可靠的声音线索。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-013">回看本课</a></p><h2 id="lesson-14-·-although-与-despite" tabindex="-1">Lesson 14 · although 与 despite <a class="header-anchor" href="#lesson-14-·-although-与-despite" aria-label="Permalink to &quot;Lesson 14 · although 与 despite {#lesson-14-·-although-与-despite}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Although the businessman funded a clinic, his illegal methods still harmed the community.</p><h3 id="练习-1-13" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-13" aria-label="Permalink to &quot;练习 1 {#练习-1-13}&quot;">​</a></h3><p>改写：Although she was wealthy, she lived simply.（用 despite）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Despite being wealthy, she lived simply.</p><p><strong>解析：</strong> 介词后用动名词结构。</p></details><p><strong>表达迁移：</strong> 用三句评价一位虚构人物，承认贡献，再说明具体问题和判断标准。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Although the director created many jobs, she ignored repeated safety complaints. Several workers had to replace damaged equipment themselves. A fair assessment must consider both employment and working conditions.</p><p>评价建立在两类具体行为上，最后一句明确衡量维度。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-014">回看本课</a></p><h2 id="lesson-15-·-数量修饰语与-worth" tabindex="-1">Lesson 15 · 数量修饰语与 worth <a class="header-anchor" href="#lesson-15-·-数量修饰语与-worth" aria-label="Permalink to &quot;Lesson 15 · 数量修饰语与 worth {#lesson-15-·-数量修饰语与-worth}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> A two-minute repair saved a toy worth only three pounds.</p><h3 id="练习-1-14" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-14" aria-label="Permalink to &quot;练习 1 {#练习-1-14}&quot;">​</a></h3><p>填空：It is worth ___.（repairing/to repair）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> repairing</p><p><strong>解析：</strong> worth 后可接动名词。</p></details><p><strong>表达迁移：</strong> 用三句写一个小物件造成的麻烦，包含价值和处理时长。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>A cheap token became trapped in the machine. A fifteen-minute inspection revealed a bent metal strip. The token was worth little, but the delay affected the whole queue.</p><p>物件价值与延误成本分开叙述，复合形容词准确限定检查时间。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-015">回看本课</a></p><h2 id="lesson-16-·-one、it-与名词替代" tabindex="-1">Lesson 16 · one、it 与名词替代 <a class="header-anchor" href="#lesson-16-·-one、it-与名词替代" aria-label="Permalink to &quot;Lesson 16 · one、it 与名词替代 {#lesson-16-·-one、it-与名词替代}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> Of the two lambs, the one with a dark ear belonged to our neighbour.</p><h3 id="练习-1-15" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-15" aria-label="Permalink to &quot;练习 1 {#练习-1-15}&quot;">​</a></h3><p>填空：My cup broke, so I bought a new ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> one</p><p><strong>解析：</strong> 表示同类中的另一个可数物品。</p></details><p><strong>表达迁移：</strong> 用三句区分两件相似物品，正确使用 one 与 it。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Two grey coats were left in the hall. The one with wooden buttons is mine. I will collect it after the meeting.</p><p>one 选择同类中的某件，it 再指已经确定的那件外套。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-016">回看本课</a></p><h2 id="lesson-17-·-最高级的范围与倍数" tabindex="-1">Lesson 17 · 最高级的范围与倍数 <a class="header-anchor" href="#lesson-17-·-最高级的范围与倍数" aria-label="Permalink to &quot;Lesson 17 · 最高级的范围与倍数 {#lesson-17-·-最高级的范围与倍数}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The new footbridge is twice as long as the wooden one it replaced.</p><h3 id="练习-1-16" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-16" aria-label="Permalink to &quot;练习 1 {#练习-1-16}&quot;">​</a></h3><p>旧桥长40米，例句中的新桥多长？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 80米。</p><p><strong>解析：</strong> twice as long 表示两倍长度。</p></details><p><strong>表达迁移：</strong> 给两座虚构桥梁写三句比较，注明指标和范围。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Bridge A has a central span of eighty metres. Bridge B&#39;s central span is twice as long. Among the three bridges in our model, Bridge B has the longest central span.</p><p>三句使用同一指标 central span，并给出最高级的比较集合。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-017">回看本课</a></p><h2 id="lesson-18-·-感官动词后的补语" tabindex="-1">Lesson 18 · 感官动词后的补语 <a class="header-anchor" href="#lesson-18-·-感官动词后的补语" aria-label="Permalink to &quot;Lesson 18 · 感官动词后的补语 {#lesson-18-·-感官动词后的补语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We watched the metal rings rotating while a low tone filled the room.</p><h3 id="练习-1-17" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-17" aria-label="Permalink to &quot;练习 1 {#练习-1-17}&quot;">​</a></h3><p>改正：I heard the bell to ring.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I heard the bell ring.</p><p><strong>解析：</strong> 主动 hear 加宾语后用动词原形表达动作事实。</p></details><p><strong>表达迁移：</strong> 用三句描述一件虚构互动作品，先写观察，再写机制和感受。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I noticed a red disk moving behind the glass. It slowed down when visitors stopped clapping. The changing rhythm made the room feel unexpectedly quiet.</p><p>前两句描述可观察变化，第三句才表达体验。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-018">回看本课</a></p><h2 id="lesson-19-·-have-加宾语加过去分词" tabindex="-1">Lesson 19 · have 加宾语加过去分词 <a class="header-anchor" href="#lesson-19-·-have-加宾语加过去分词" aria-label="Permalink to &quot;Lesson 19 · have 加宾语加过去分词 {#lesson-19-·-have-加宾语加过去分词}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> After the gate broke, we had a new lock fitted to keep the dog safely inside.</p><h3 id="练习-1-18" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-18" aria-label="Permalink to &quot;练习 1 {#练习-1-18}&quot;">​</a></h3><p>填空：We had the fence ___.（repair/repaired）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> repaired</p><p><strong>解析：</strong> 宾语 fence 承受修理动作。</p></details><p><strong>表达迁移：</strong> 写三句宠物走失后的处理，包含安排服务和最终结果。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Our puppy escaped through a broken panel. We had the fence repaired that afternoon. A neighbour found the puppy near the bus stop.</p><p>维修安排与找回宠物是两个独立动作，没有暗示维修本身找回了宠物。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-019">回看本课</a></p><h2 id="lesson-20-·-过去将来时与计划结果" tabindex="-1">Lesson 20 · 过去将来时与计划结果 <a class="header-anchor" href="#lesson-20-·-过去将来时与计划结果" aria-label="Permalink to &quot;Lesson 20 · 过去将来时与计划结果 {#lesson-20-·-过去将来时与计划结果}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The pilot believed that the lighter engine would extend the aircraft&#39;s range.</p><h3 id="练习-1-19" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-19" aria-label="Permalink to &quot;练习 1 {#练习-1-19}&quot;">​</a></h3><p>例句是否证明航程后来真的增加？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> 它只报告飞行员当时的判断。</p></details><p><strong>表达迁移：</strong> 写三句虚构飞行试验记录，分别表达计划、阻碍和实际行动。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The team was going to test the glider on Monday. Strong winds made the hillside unsafe. They postponed the flight and inspected the frame instead.</p><p>第一句为过去计划，后二句明确未按计划进行，时间逻辑完整。</p></details><p><a href="/life/english/new-concept/book-3/unit-01/lesson-020">回看本课</a></p><h2 id="lesson-21-·-完成时不定式的先后关系" tabindex="-1">Lesson 21 · 完成时不定式的先后关系 <a class="header-anchor" href="#lesson-21-·-完成时不定式的先后关系" aria-label="Permalink to &quot;Lesson 21 · 完成时不定式的先后关系 {#lesson-21-·-完成时不定式的先后关系}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The retired athlete appears to have inspired a new generation of coaches.</p><h3 id="练习-1-20" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-20" aria-label="Permalink to &quot;练习 1 {#练习-1-20}&quot;">​</a></h3><p>例句的启发发生在判断之前还是之后？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 之前。</p><p><strong>解析：</strong> 完成时不定式表示更早的动作。</p></details><p><strong>表达迁移：</strong> 用三句写虚构运动员的小传，包含可见成绩、谨慎评价和具体影响。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>Elena won her first regional title at nineteen. She seems to have influenced several younger runners. Two of them now use the training diary she designed.</p><p>事实先行，谨慎评价后接具体证据，避免空泛赞扬。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-021">回看本课</a></p><h2 id="lesson-22-·-should-have-done-的过去评价" tabindex="-1">Lesson 22 · should have done 的过去评价 <a class="header-anchor" href="#lesson-22-·-should-have-done-的过去评价" aria-label="Permalink to &quot;Lesson 22 · should have done 的过去评价 {#lesson-22-·-should-have-done-的过去评价}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I missed my cue because I had not rehearsed; I should have checked the recording twice.</p><h3 id="练习-1-21" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-21" aria-label="Permalink to &quot;练习 1 {#练习-1-21}&quot;">​</a></h3><p>本例中说话者是否充分排练？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> had not rehearsed 明确否定。</p></details><p><strong>表达迁移：</strong> 写三句演讲复盘，包含一次失误、原因和具体改进。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I forgot the opening line during the rehearsal. I should have practised without looking at my notes. Tomorrow I will use three picture cues instead of a full script.</p><p>过去评价之后给出可操作的未来策略，避免只重复“多努力”。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-022">回看本课</a></p><h2 id="lesson-23-·-prefer-与-would-rather" tabindex="-1">Lesson 23 · prefer 与 would rather <a class="header-anchor" href="#lesson-23-·-prefer-与-would-rather" aria-label="Permalink to &quot;Lesson 23 · prefer 与 would rather {#lesson-23-·-prefer-与-would-rather}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I prefer tasting a small portion to rejecting an unfamiliar dish immediately.</p><h3 id="练习-1-22" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-22" aria-label="Permalink to &quot;练习 1 {#练习-1-22}&quot;">​</a></h3><p>填空：I would rather ___ at home.（eat/eating）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> eat</p><p><strong>解析：</strong> would rather 后接原形。</p></details><p><strong>表达迁移：</strong> 写三句解释一种个人饮食偏好，包含理由并承认差异。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I prefer mild soup to very spicy dishes. A gentle flavour lets me notice the vegetables. My brother enjoys stronger seasoning, so we add spices at the table.</p><p>偏好归属于具体人物，实际安排兼顾差异。</p></details><p><a href="/life/english/new-concept/book-3/unit-02/lesson-023">回看本课</a></p>',100)])])}const m=s(n,[["render",r]]);export{g as __pageData,m as default};
